/* Analyser - lazy parser chunk: OS-specific / system / misc / obscure formats.

   Loaded on demand by renderProprietary() when a file whose FORMATS entry has
   `chunk: 'osmisc'` is opened. Each entry in PARSERS is
   `({head, file, ext}) => rows` where `rows` is a plain object of label->value
   pairs (rendered as a readout), optionally carrying `_sections:[{title,node,
   open?}]` for collapsible blocks or `_previewNode`. Return null to fall back to
   the generic identification card.

   Dependency-free: only the shared toolkit (util/binutil) and the shared
   Apple plist reader (lib/plist) are imported. */

import { el, fmtBytes, preBlock, fmtDate, readSlice, readText } from '../core/util.js';
import type { ElChild, ElAttrs } from '../core/util.js';
import { Reader, ascii, cp437, latin1, utf8 } from '../core/binutil.js';
import { PARSE_TEXT_MAX, SCAN_SMALL } from '../core/limits.js';
import { parsePlist, unarchiveKeyed } from '../lib/plist.js';
import type { Row, ParseFn } from '../core/types.js';

// ---------- small helpers ----------
// A monospace block that preserves ASCII art (no wrapping, horizontal scroll).
function monoBlock(text: string) {
  return el('pre', { class: 'anr-code', style: 'max-height:480px;overflow:auto;font-size:12px;line-height:1.2;white-space:pre;margin:0;font-family:monospace;' }, text);
}

// Parse an INI / freedesktop-style file into { section: { key: value } } plus an
// ordered list of section names. Comments (#, ;) and blank lines are skipped.
function parseIni(text: string) {
  const out: any = {}; const order = [];
  let cur = '';
  out[cur] = {};
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line[0] === '#' || line[0] === ';') continue;
    const sec = line.match(/^\[(.+)\]$/);
    if (sec) {
      cur = sec[1];
      if (!out[cur]) { out[cur] = {}; order.push(cur); }
      continue;
    }
    const eq = line.indexOf('=');
    if (eq < 0) continue;
    const k = line.slice(0, eq).trim();
    const v = line.slice(eq + 1).trim();
    if (out[cur][k] == null) out[cur][k] = v;
  }
  return { sections: out, order };
}

// First DOM element matching a tag name (case-insensitive), searched across the
// whole document; returns its trimmed textContent or ''.
function xmlText(doc: ParentNode, sel: string) {
  const n = doc.querySelector(sel);
  return n ? (n.textContent || '').trim() : '';
}

// ---------- OPML ----------
async function parseOpml(file: File) {
  const text = await readText(file, PARSE_TEXT_MAX);
  const doc = new DOMParser().parseFromString(text, 'application/xml');
  if (doc.querySelector('parsererror') || !doc.querySelector('opml')) return null;
  const out: Row = { 'Format': 'OPML outline' };
  const head = doc.querySelector('head');
  if (head) {
    const title = xmlText(head, 'title');
    const created = xmlText(head, 'dateCreated');
    const owner = xmlText(head, 'ownerName');
    if (title) out['Title'] = title;
    if (created) out['Date created'] = created;
    if (owner) out['Owner'] = owner;
  }
  const ver = doc.querySelector('opml')!.getAttribute('version');
  if (ver) out['Version'] = ver;
  // Feed outlines carry an xmlUrl attribute.
  const outlines = Array.from(doc.querySelectorAll('outline'));
  const feeds = outlines.filter((o) => o.getAttribute('xmlUrl'));
  out['Outline nodes'] = outlines.length;
  out['Feeds (subscriptions)'] = feeds.length;
  if (feeds.length) {
    const lines = feeds.slice(0, 500).map((o) => {
      const t = o.getAttribute('title') || o.getAttribute('text') || '(untitled)';
      const x = o.getAttribute('xmlUrl') || '';
      const h = o.getAttribute('htmlUrl');
      return t + '\n    xml:  ' + x + (h ? '\n    html: ' + h : '');
    });
    out._sections = [{ title: 'Feeds (' + feeds.length + ')', node: preBlock(lines.join('\n\n')), open: feeds.length <= 40 }];
  }
  return out;
}

// ---------- RSS / Atom ----------
async function parseFeed(file: File) {
  const text = await readText(file, PARSE_TEXT_MAX);
  const doc = new DOMParser().parseFromString(text, 'application/xml');
  if (doc.querySelector('parsererror')) return null;
  const isAtom = !!doc.querySelector('feed');
  const isRss = !!doc.querySelector('rss, rdf\\:RDF, RDF');
  if (!isAtom && !isRss) return null;

  const out: any = {};
  let items, enclosures = [];
  const dates = [];

  if (isAtom) {
    out['Format'] = 'Atom feed';
    const feed = doc.querySelector('feed');
    out['Title'] = xmlText(feed!, 'title') || '-';
    const sub = xmlText(feed!, 'subtitle'); if (sub) out['Subtitle'] = sub;
    out['Items (entries)'] = (items = Array.from(doc.querySelectorAll('entry'))).length;
    for (const e of items) {
      const d = xmlText(e, 'updated') || xmlText(e, 'published');
      if (d) dates.push(new Date(d));
      for (const l of Array.from<Element>(e.querySelectorAll('link'))) {
        if (l.getAttribute('rel') === 'enclosure' && l.getAttribute('href')) {
          enclosures.push({ url: l.getAttribute('href'), len: l.getAttribute('length') });
        }
      }
    }
  } else {
    out['Format'] = 'RSS feed';
    const chan = doc.querySelector('channel') || doc.documentElement;
    out['Title'] = xmlText(chan, 'title') || '-';
    const desc = xmlText(chan, 'description'); if (desc) out['Description'] = desc.slice(0, 200);
    const lang = xmlText(chan, 'language'); if (lang) out['Language'] = lang;
    out['Items'] = (items = Array.from(doc.querySelectorAll('item'))).length;
    for (const it of items) {
      const d = xmlText(it, 'pubDate') || xmlText(it, 'date');
      if (d) dates.push(new Date(d));
      for (const en of Array.from<Element>(it.querySelectorAll('enclosure'))) {
        if (en.getAttribute('url')) enclosures.push({ url: en.getAttribute('url'), len: en.getAttribute('length') });
      }
    }
  }

  const valid = dates.filter((d) => d instanceof Date && !isNaN(d.getTime()));
  if (valid.length) {
    // Math.min/max coerce each Date through valueOf(); the cast only says so.
    const nums = valid as unknown as number[];
    const min = new Date(Math.min(...nums)), max = new Date(Math.max(...nums));
    out['Date range'] = fmtDate(min) + '  →  ' + fmtDate(max);
  }
  if (enclosures.length) {
    out['Enclosures'] = enclosures.length;
    const lines = enclosures.slice(0, 300).map((e) => e.url + (e.len ? '  (' + fmtBytes(parseInt(e.len, 10)) + ')' : ''));
    out._sections = [{ title: 'Enclosures (' + enclosures.length + ')', node: preBlock(lines.join('\n')) }];
  }
  return out;
}

// ---------- .desktop (freedesktop entry) ----------
async function parseDesktop(file: File) {
  const text = await readText(file, PARSE_TEXT_MAX);
  if (!/\[Desktop Entry\]/.test(text)) return null;
  const { sections } = parseIni(text);
  const e = sections['Desktop Entry'] || {};
  const out: Record<string, string> = { 'Format': 'Freedesktop .desktop entry' };
  for (const [k, label] of [['Type', 'Type'], ['Name', 'Name'], ['GenericName', 'Generic name'],
    ['Comment', 'Comment'], ['Exec', 'Exec'], ['TryExec', 'TryExec'], ['Icon', 'Icon'],
    ['Categories', 'Categories'], ['MimeType', 'MIME types'], ['Terminal', 'Terminal'],
    ['NoDisplay', 'NoDisplay'], ['Hidden', 'Hidden'], ['Version', 'Spec version']]) {
    if (e[k] != null) out[label] = e[k];
  }
  return out;
}

// ---------- .nfo (CP437 scene art, or XML sidecar) ----------
async function parseNfo(file: File) {
  const bytes = await readSlice(file, 0, 2_000_000);
  // Skip a UTF-8/UTF-16 BOM when deciding XML-vs-art.
  let i = 0;
  if (bytes[0] === 0xEF && bytes[1] === 0xBB && bytes[2] === 0xBF) i = 3;
  const firstNonWs = (() => { let p = i; while (p < bytes.length && (bytes[p] === 0x20 || bytes[p] === 0x09 || bytes[p] === 0x0A || bytes[p] === 0x0D)) p++; return bytes[p]; })();
  const isXml = firstNonWs === 0x3C; // '<'

  let textOut;
  if (isXml) {
    textOut = utf8(bytes);
  } else {
    textOut = cp437(bytes);
  }
  const lines = textOut.split(/\r?\n/);
  const out: Row = {
    'Format': isXml ? 'NFO (XML sidecar)' : 'NFO (scene info, CP437)',
    'Encoding': isXml ? 'UTF-8 / XML' : 'CP437 (DOS OEM)',
    'Lines': lines.length,
    'Characters': textOut.length,
  };
  const shown = textOut.length > 200000 ? textOut.slice(0, 200000) + '\n…(truncated)' : textOut;
  out._sections = [{ title: isXml ? 'Document' : 'ASCII art', node: monoBlock(shown), open: true }];
  return out;
}

// ---------- systemd .service unit ----------
async function parseService(file: File) {
  const text = await readText(file, PARSE_TEXT_MAX);
  if (!/\[Unit\]|\[Service\]|\[Install\]/.test(text)) return null;
  const { sections } = parseIni(text);
  const unit = sections['Unit'] || {}, svc = sections['Service'] || {}, inst = sections['Install'] || {};
  const out: Row = { 'Format': 'systemd unit file' };
  if (unit['Description']) out['Description'] = unit['Description'];
  if (svc['Type']) out['Service type'] = svc['Type'];
  if (svc['ExecStart']) out['ExecStart'] = svc['ExecStart'];
  if (svc['ExecStop']) out['ExecStop'] = svc['ExecStop'];
  if (svc['User']) out['User'] = svc['User'];
  if (svc['Restart']) out['Restart'] = svc['Restart'];
  if (svc['WorkingDirectory']) out['Working directory'] = svc['WorkingDirectory'];
  const deps = [];
  for (const k of ['Requires', 'Wants', 'After', 'Before', 'BindsTo', 'PartOf']) {
    if (unit[k]) deps.push(k + '=' + unit[k]);
  }
  if (deps.length) out['Dependencies'] = deps.length;
  if (inst['WantedBy']) out['WantedBy'] = inst['WantedBy'];
  if (inst['RequiredBy']) out['RequiredBy'] = inst['RequiredBy'];
  if (deps.length) out._sections = [{ title: 'Dependencies', node: preBlock(deps.join('\n')) }];
  return out;
}

// ---------- .crash / Apple .ips crash report ----------
async function parseCrash(file: File) {
  const text = await readText(file, 2_000_000);
  const trimmed = text.replace(/^﻿/, '').trimStart();

  // Apple .ips: a JSON header line, then a JSON body. Or a single JSON object.
  if (trimmed[0] === '{') {
    return parseAppleCrash(trimmed);
  }
  // Plain-text crash log (legacy Apple / generic).
  return parseTextCrash(text);
}

function parseAppleCrash(text: string) {
  // Try whole-document JSON first.
  let whole = null;
  try { whole = JSON.parse(text); } catch (_) {}
  let header = null, body = null;
  if (whole && (whole.app_name || whole.bug_type || whole.timestamp) && !whole.product) {
    // Some .ips are a single object; treat it as the body and also harvest header-ish keys.
    header = whole; body = whole;
  } else {
    // Header line + body: split on the first newline that ends a complete JSON object.
    const nl = text.indexOf('\n');
    if (nl > 0) {
      try { header = JSON.parse(text.slice(0, nl)); } catch (_) {}
      try { body = JSON.parse(text.slice(nl + 1)); } catch (_) {}
    }
    if (!body) { try { body = JSON.parse(text); } catch (_) {} }
  }
  if (!header && !body) return null;
  const h = header || {}, b = body || {};
  const out: Row = { 'Format': 'Apple crash report (.ips)' };
  const app = b.procName || h.app_name || (b.application_specific_information && b.app_name);
  if (app) out['Process / app'] = app;
  if (h.app_version || b.bundleInfo) out['Version'] = h.app_version || (b.bundleInfo && b.bundleInfo.CFBundleShortVersionString) || '-';
  const bundle = (b.bundleInfo && b.bundleInfo.CFBundleIdentifier) || h.bundleID || b.coalitionName;
  if (bundle) out['Bundle ID'] = bundle;
  if (h.bug_type) out['Bug type'] = h.bug_type;
  if (h.os_version || (b.osVersion && b.osVersion.train)) out['OS version'] = h.os_version || b.osVersion.train;
  if (h.incident_id) out['Incident ID'] = h.incident_id;
  if (h.timestamp || b.captureTime) out['Timestamp'] = h.timestamp || b.captureTime;
  const model = b.modelCode || h.model || (b.deviceInfo);
  if (model) out['Device'] = model;
  if (b.exception) {
    const ex = b.exception;
    if (ex.type) out['Exception type'] = ex.type + (ex.signal ? ' (' + ex.signal + ')' : '');
    if (ex.codes) out['Exception codes'] = ex.codes;
    if (ex.subtype) out['Exception subtype'] = ex.subtype;
  }
  if (typeof b.faultingThread === 'number') out['Faulting thread'] = b.faultingThread;
  if (b.termination) out['Termination'] = (b.termination.indicator || '') + (b.termination.reasons ? ' ' + b.termination.reasons.join(' ') : '');
  // Binary images / UUIDs.
  if (Array.isArray(b.usedImages)) {
    out['Loaded images'] = b.usedImages.length;
    const uuids = b.usedImages.slice(0, 50).map((im: any) => (im.name || '?') + '  ' + (im.uuid || ''));
    out._sections = [{ title: 'Binary images (' + b.usedImages.length + ')', node: preBlock(uuids.join('\n')) }];
  }
  return out;
}

function parseTextCrash(text: string) {
  const out: Row = { 'Format': 'Crash report (text)' };
  const grab = (re: RegExp) => { const m = text.match(re); return m ? m[1].trim() : null; };
  const fields: [string, RegExp][] = [
    ['Process', /^Process:\s*(.+)$/m],
    ['Identifier', /^Identifier:\s*(.+)$/m],
    ['Version', /^Version:\s*(.+)$/m],
    ['OS Version', /^OS Version:\s*(.+)$/m],
    ['Hardware Model', /^Hardware Model:\s*(.+)$/m],
    ['Exception Type', /^Exception Type:\s*(.+)$/m],
    ['Exception Codes', /^Exception Codes:\s*(.+)$/m],
    ['Crashed Thread', /^Crashed Thread:\s*(.+)$/m],
  ];
  let any = false;
  for (const [label, re] of fields) { const v = grab(re); if (v) { out[label] = v; any = true; } }
  // Generic fallback: count UUIDs and dump first lines.
  const uuids = (text.match(/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}/g) || []);
  if (uuids.length) out['UUID references'] = new Set(uuids).size;
  if (!any && !uuids.length && !/Thread \d+|backtrace|signal/i.test(text)) return null;
  out['Lines'] = text.split(/\r?\n/).length;
  out._sections = [{ title: 'Report', node: monoBlock(text.length > 200000 ? text.slice(0, 200000) + '\n…' : text) }];
  return out;
}

// ---------- .ab Android Backup ----------
async function parseAb(file: File) {
  const head = new Uint8Array(await file.slice(0, 64).arrayBuffer());
  if (ascii(head, 0, 14) !== 'ANDROID BACKUP') return null;
  // Format: 5 newline-terminated text lines: magic, version, compressed flag,
  // encryption algorithm, [encryption params...]. Then the tar payload.
  const text = latin1(head);
  const lines = text.split('\n');
  const out: Row = { 'Format': 'Android Backup (.ab)' };
  const version = lines[1] || '';
  const compressed = lines[2] || '';
  const encryption = lines[3] || '';
  out['Backup version'] = version || '?';
  out['Compression'] = compressed === '1' ? 'zlib (deflate)' : compressed === '0' ? 'none' : compressed;
  out['Encryption'] = (encryption && encryption !== 'none') ? encryption : 'none';
  if (compressed === '0' && (!encryption || encryption === 'none')) {
    out['Payload'] = 'uncompressed tar stream follows the header';
  } else {
    out['Payload'] = 'deflate-compressed tar' + (encryption && encryption !== 'none' ? ', AES-encrypted' : '') + ' (adb backup)';
  }
  return out;
}

// ---------- .job Windows Task Scheduler (legacy v1) ----------
async function parseJob(file: File) {
  const b = await readSlice(file, 0, 8192);
  if (b.length < 0x44) return null;
  const r = new Reader(b, true); // little-endian
  // FIXDLEN_DATA header (.job v1 format).
  const productVersion = r.u16();
  const fileVersion = r.u16();
  if (fileVersion !== 1) return null; // sanity: known .job file version is 1
  r.skip(16); // UUID
  const appNameOffset = r.u16();
  const triggerOffset = r.u16();
  const errorRetryCount = r.u16();
  const errorRetryInterval = r.u16();
  const idleDeadline = r.u16();
  const idleWait = r.u16();
  const priority = r.u32();
  const maxRunTime = r.u32();
  const exitCode = r.u32();
  const status = r.u32();
  const flags = r.u32();

  const PRODUCTS: Record<number, string> = { 0x0400: 'Windows NT 4.0', 0x0500: 'Windows 2000', 0x0501: 'Windows XP', 0x0600: 'Windows Vista' };
  const out: Row = {
    'Format': 'Windows Task Scheduler job (.job v1)',
    'Product version': PRODUCTS[productVersion] || ('0x' + productVersion.toString(16)),
    'File format version': fileVersion,
    'Error retry count': errorRetryCount,
    'Max run time (ms)': maxRunTime === 0xFFFFFFFF ? 'infinite' : maxRunTime,
    'Priority flags': '0x' + priority.toString(16),
  };

  // Variable-length section starts at appNameOffset: each field is a Unicode
  // counted string (u16 length in chars, then UTF-16LE chars incl. trailing NUL).
  try {
    let p = appNameOffset;
    const readUStr = () => {
      if (p + 2 > b.length) return null;
      const len = b[p] | (b[p + 1] << 8); p += 2;
      const bytes = len * 2;
      if (bytes < 0 || p + bytes > b.length) { return null; }
      const s = new TextDecoder('utf-16le').decode(b.subarray(p, p + bytes)).replace(/\0+$/, '');
      p += bytes;
      return s;
    };
    // AppNameLenOffset (MS-TSCH) points straight at the application name's length
    // word - the running instance count before it is already behind us.
    const appName = readUStr();
    const params = readUStr();
    const workingDir = readUStr();
    const author = readUStr();
    const comment = readUStr();
    if (appName) out['Application'] = appName;
    if (params) out['Parameters'] = params;
    if (workingDir) out['Working directory'] = workingDir;
    if (author) out['Author'] = author;
    if (comment) out['Comment'] = comment;
  } catch (_) {}
  return out;
}

// ---------- .pol Group Policy Registry.pol ----------
async function parsePol(file: File) {
  const b = await readSlice(file, 0, 1_000_000);
  // Header: "PReg" (0x67655250 LE) + version u32.
  if (!(b[0] === 0x50 && b[1] === 0x52 && b[2] === 0x65 && b[3] === 0x67)) return null;
  const r = new Reader(b, true);
  r.skip(4);
  const version = r.u32();
  // Records: '[' key ; value ; type ; size ; data ']' all UTF-16LE, ';' = 0x3B00.
  // Count opening '[' (0x5B 0x00) brackets that start a record.
  let records = 0;
  for (let i = 8; i + 1 < b.length; i += 2) {
    if (b[i] === 0x5B && b[i + 1] === 0x00) records++;
  }
  return {
    'Format': 'Group Policy Registry.pol',
    'Signature': 'PReg',
    'Version': version,
    'Policy records': records,
    'Note': 'Each record = [key;value;type;size;data] applied to HKLM/HKCU',
  };
}

// Adobe Font List (AdobeFnt*.lst) - the font cache Adobe apps (Photoshop,
// Illustrator, InDesign, Acrobat) write to catalogue every font they can see.
// PostScript-comment header (%!Adobe-FontList <ver>) then one %BeginFont /
// %EndFont block per font, each a set of Key:Value lines (FontType, FamilyName,
// OutlineFileName, FileLength, WeightClass, WritingScript, native names, ...).
async function parseFontList(file: File) {
  const text = await readText(file, 16_000_000);
  const verM = text.match(/^%!Adobe-FontList\s+([\d.]+)/);
  if (!verM) return null;                                   // not an Adobe font list
  const localeM = text.match(/^%Locale:\s*(\S+)/m);
  const fonts = text.split(/^%BeginFont\b/m).slice(1).map((b) => {
    const e = b.search(/^%EndFont\b/m);
    const f: any = {};
    for (const line of (e >= 0 ? b.slice(0, e) : b).split(/\r?\n/)) {
      const c = line.indexOf(':');
      if (c < 0) continue;
      const k = line.slice(0, c).trim();
      if (k && !(k in f)) f[k] = line.slice(c + 1);          // keep first (NameArray repeats)
    }
    return f;
  });

  const out: any = {};
  out._app = 'Adobe Font List';                              // refine the card title from the generic "List / Index File"
  out['Format'] = 'Adobe Font List ' + verM[1];
  if (localeM) out['Locale'] = localeM[1];
  out['Fonts catalogued'] = String(fonts.length);

  const tally: any = {}, scripts: any = {};
  let totalBytes = 0, variable = 0, svg = 0;
  const families = new Set();
  for (const f of fonts) {
    if (f.FontType) tally[f.FontType] = (tally[f.FontType] || 0) + 1;
    if (f.WritingScript) scripts[f.WritingScript] = (scripts[f.WritingScript] || 0) + 1;
    const len = parseInt(f.FileLength, 10); if (isFinite(len)) totalBytes += len;
    if (f.VariableFontType && f.VariableFontType !== 'NonVariableFont') variable++;
    if (f.hasSVG === 'yes') svg++;
    if (f.FamilyName) families.add(f.FamilyName.trim());
  }
  const brk = (o: Record<string, number>) => Object.entries<number>(o).sort((a, b) => b[1] - a[1]).map(([k, v]) => k + ' (' + v + ')').join(', ');
  out['Unique families'] = String(families.size);
  if (Object.keys(tally).length) out['Font types'] = brk(tally);
  if (Object.keys(scripts).length) out['Writing scripts'] = brk(scripts);
  if (variable) out['Variable fonts'] = String(variable);
  if (svg) out['SVG colour fonts'] = String(svg);
  if (totalBytes) out['Total font data'] = fmtBytes(totalBytes);

  // Source roots: the common directories the catalogued fonts live in.
  const roots: Record<string, number> = {};
  for (const f of fonts) {
    const p = (f.OutlineFileName || '').trim();
    if (!p) continue;
    const dir = p.slice(0, Math.max(p.lastIndexOf('/'), p.lastIndexOf('\\')));
    if (dir) roots[dir] = (roots[dir] || 0) + 1;
  }
  const topRoots = Object.entries(roots).sort((a, b) => b[1] - a[1]).slice(0, 6);

  const th = (t: ElChild) => el('th', { style: 'text-align:left;padding:4px 8px;border-bottom:1px solid var(--hairline);position:sticky;top:0;background:var(--surface)' }, t);
  const td = (v: ElChild | ElChild[], extra?: ElAttrs | null) => el('td', Object.assign({ style: 'padding:3px 8px;border-bottom:1px solid var(--hairline);white-space:nowrap' }, extra || {}), v);
  const rows = fonts.slice(0, 600).map((f) => {
    const name = (f.FamilyName || f.FullName || f.FontName || '?').trim() + (f.StyleName && f.StyleName.trim() && f.StyleName.trim() !== 'Regular' ? ' ' + f.StyleName.trim() : '');
    const path = (f.OutlineFileName || '').trim();
    const base = path ? path.slice(Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\')) + 1) : '';
    const ttc = f.TTCOffset && f.TTCOffset.trim() && f.TTCOffset.trim() !== '0' ? ' #' + f.TTCOffset.trim() : '';
    const len = parseInt(f.FileLength, 10);
    const nativeName = (f.FullNameNative || f.FamilyNameNative || '').trim();
    return el('tr', {}, [
      td(name, nativeName ? { title: nativeName } : null),
      td(nativeName && nativeName !== name ? nativeName : '', { style: 'padding:3px 8px;border-bottom:1px solid var(--hairline);white-space:nowrap;opacity:.75' }),
      td((f.FontType || '').trim()),
      td((f.WeightClass || '').trim()),
      td((f.WritingScript || '').trim()),
      td(isFinite(len) ? fmtBytes(len) : ''),
      td(base + ttc, { title: path, style: 'padding:3px 8px;border-bottom:1px solid var(--hairline);font-family:var(--font-mono);font-size:11px;max-width:280px;overflow:hidden;text-overflow:ellipsis' }),
    ]);
  });
  const table = el('div', { style: 'overflow:auto;max-height:520px' }, [
    el('table', { style: 'border-collapse:collapse;font-size:12.5px;width:100%' }, [
      el('thead', {}, el('tr', {}, [th('Font'), th('Native name'), th('Type'), th('Weight'), th('Script'), th('Size'), th('Source file')])),
      el('tbody', {}, rows),
    ]),
  ]);

  out._sections = [{ title: 'Catalogued fonts (' + fonts.length + (fonts.length > 600 ? ', first 600 shown' : '') + ')', node: table, open: true }];
  if (topRoots.length) out._sections.push({ title: 'Font folders (' + Object.keys(roots).length + ')', node: preBlock(topRoots.map(([d, n]) => n + '  ' + d).join('\n')), open: topRoots.length <= 6 });
  return out;
}

// ---------- identification-only (rare AND hard) ----------
function identDsStore() {
  return { 'Format': 'macOS .DS_Store', 'Note': 'Finder folder-view metadata (Buddy-allocator B-tree). Identification only.' };
}
function identThumbsDb() {
  return { 'Format': 'Windows Thumbs.db', 'Note': 'OLE compound thumbnail cache (legacy Windows Explorer). Identification only.' };
}
function identDsym() {
  return { 'Format': 'dSYM / DWARF debug info', 'Note': 'Mach-O debug symbols (DWARF). Identification only.' };
}
function identSdb() {
  return { 'Format': 'Windows Shim Database (.sdb)', 'Note': 'Application Compatibility shim database. Identification only.' };
}

// ---------- Android shared-preferences XML / GCam config (.agc) ----------
// Android stores app settings as <map> XML (<string>/<int>/<boolean>/<float>
// children). Google Camera ports (GCam) ship their tuning as .agc files in this
// exact shape, so read the entry counts by type and the key list.
async function parseAndroidPrefs(file: File, ext: string) {
  const text = await readText(file, 4_000_000);
  if (!/<map\b/.test(text)) return null;
  const doc = new DOMParser().parseFromString(text, 'application/xml');
  if (doc.querySelector('parsererror')) return null;
  const map = doc.querySelector('map');
  if (!map) return null;
  const kids = Array.from(map.children);
  const byTag: any = {};
  for (const k of kids) byTag[k.tagName] = (byTag[k.tagName] || 0) + 1;
  const gcam = ext === 'agc' || /\b(lib_luma|sabre|hdr|libpatcher|saturation|awb)\b/i.test(text);
  const out: Row = {
    'Format': gcam ? 'Google Camera (GCam) config (.agc)' : 'Android shared-preferences XML',
    'Entries': kids.length,
  };
  if (Object.keys(byTag).length) out['By type'] = Object.entries(byTag).map(([k, v]) => k + ': ' + v).join('   ');
  const names = kids.map((k) => k.getAttribute('name')).filter(Boolean);
  if (names.length) out._sections = [{ title: 'Keys (' + names.length + ')', node: preBlock(names.slice(0, 400).join('\n')) }];
  return out;
}

// ---------- Samsung Secure Folder / Smart Switch encrypted (.penc / .enc) ----------
// Knox-encrypted blobs from a Samsung phone backup. .penc (packed encrypted app)
// has a fixed 00 10 00 10 header; .enc (Secure Folder self item) has none. The
// payload is AES-encrypted with a device-bound key, so this is identification only.
async function parseSamsungEncrypted(file: File, ext: string) {
  const head = new Uint8Array(await file.slice(0, 8).arrayBuffer());
  const penc = head[0] === 0x00 && head[1] === 0x10 && head[2] === 0x00 && head[3] === 0x10;
  const out: Row = {
    'Format': ext === 'penc'
      ? 'Samsung Secure Folder encrypted package (.penc)'
      : 'Samsung Secure Folder / Smart Switch encrypted item (.' + ext + ')',
    'Encryption': 'AES (Samsung Knox), device-bound key',
    'Size': fmtBytes(file.size),
  };
  if (penc) out['Header'] = '00 10 00 10';
  out['Note'] = 'Encrypted on a Samsung phone (Secure Folder / Smart Switch). The original (often an APK or app data) cannot be decrypted off-device.';
  return out;
}

// ---------- Samsung Smart Switch backup container (.bk) ----------
async function parseSamsungBackup(file: File) {
  return {
    'Format': 'Backup container (.bk)',
    'Likely origin': 'Samsung Smart Switch / Kies device backup',
    'Size': fmtBytes(file.size),
    'Note': 'A per-device backup container (such as AppList.bk), usually compressed or encrypted. Contents are not unpacked in-browser; .bk is also a generic backup suffix used by other tools.',
  };
}

// ---------- macOS property-list documents ----------
// A plist value tree as readable JSON: binary data shown by size, dates as ISO.
function plistDump(v: any) {
  let json = '';
  try { json = JSON.stringify(v, (k, x) => (x instanceof Uint8Array ? '<' + x.length + ' bytes>' : x), 2) || ''; } catch (_) { return null; }
  return preBlock(json.length > 40000 ? json.slice(0, 40000) + '\n…' : json);
}
// A pasteboard / plist value that should be text: a string, or bytes in UTF-8
// (UTF-16 when the type says so or the bytes carry a BOM).
function plistText(x: any, utf16 = false) {
  if (typeof x === 'string') return x;
  if (!(x instanceof Uint8Array)) return null;
  const bom16 = x.length >= 2 && ((x[0] === 0xFF && x[1] === 0xFE) || (x[0] === 0xFE && x[1] === 0xFF));
  if (utf16 || bom16) return new TextDecoder(x[0] === 0xFE ? 'utf-16be' : 'utf-16le').decode(x);
  return new TextDecoder('utf-8').decode(x);
}
const fourcc = (n: any) => typeof n === 'number' && n > 0x20202020 ? String.fromCharCode((n >>> 24) & 255, (n >>> 16) & 255, (n >>> 8) & 255, n & 255) : String(n);

async function parseMacPlist(file: File, ext: string) {
  if (file.size > SCAN_SMALL) return null;   // these are KB-sized; a plist must be read whole
  const res = await parsePlist(file);
  if (!res) return null;
  const v = unarchiveKeyed(res.value);
  if (!v || typeof v !== 'object') return null;
  const out: Row = { 'Format': 'Property list (' + res.format + ')' };
  const sections: any[] = [];

  if (ext === 'textclipping') {
    // Text dragged out of any app onto the desktop. The clip is stored once per
    // pasteboard type (UTI) under "UTI-Data"; very old clippings keep it in a
    // resource fork only, which a copy off the Mac loses.
    const uti = (v['UTI-Data'] && typeof v['UTI-Data'] === 'object') ? v['UTI-Data'] : {};
    const types = Object.keys(uti);
    if (types.length) out['Stored as'] = types.join(', ');
    const text = plistText(uti['public.utf8-plain-text']) ?? plistText(uti['public.utf16-plain-text'], true)
      ?? plistText(uti['public.plain-text']) ?? plistText(uti['com.apple.traditional-mac-plain-text']);
    const url = plistText(uti['public.url']) || plistText(uti['public.file-url']);
    if (url) out['URL'] = url;
    if (text) {
      out['Characters'] = text.length.toLocaleString();
      sections.push({ title: 'Clipped text', node: preBlock(text.length > 200000 ? text.slice(0, 200000) + '\n…' : text), open: true });
    } else if (!types.length) out['Note'] = 'No clip data in the file. Clippings from older macOS kept it in the resource fork, which is lost when the file leaves a Mac.';
  } else if (ext === 'inetloc' || ext === 'fileloc' || ext === 'afploc' || ext === 'ftploc') {
    const u = v.URL || v.url || (v.URLPrefixLength != null && v.URL);
    if (u) out['URL'] = String(u);
    if (typeof u === 'string' && /^file:/i.test(u)) {
      try { out['Path'] = decodeURIComponent(u.replace(/^file:\/\/(localhost)?/i, '')); } catch (_) {}
    }
  } else if (ext === 'savedsearch') {
    // A Finder Smart Folder: a Spotlight query plus where it searches.
    if (v.RawQuery) out['Spotlight query'] = String(v.RawQuery);
    const sc = (v.SearchCriteria && typeof v.SearchCriteria === 'object') ? v.SearchCriteria : {};
    const scope = sc.FXScopeArrayOfPaths || sc.FXScope;
    if (Array.isArray(scope) && scope.length) out['Searches in'] = scope.map(String).join(', ');
    if (Array.isArray(sc.FXCriteriaSlices)) out['Criteria rows'] = sc.FXCriteriaSlices.length;
    if (v.CompatibleVersion != null) out['Format version'] = String(v.CompatibleVersion);
  } else if (ext === 'terminal') {
    if (v.name) out['Profile name'] = String(v.name);
    if (v.columnCount || v.rowCount) out['Window'] = (v.columnCount || '?') + ' x ' + (v.rowCount || '?') + ' characters';
    if (v.CommandString) out['Runs command'] = String(v.CommandString);
    // Font and colours are themselves NSKeyedArchiver archives nested as data.
    if (v.Font instanceof Uint8Array) {
      try {
        const f = await parsePlist(v.Font);
        const fv = f && unarchiveKeyed(f.value);
        if (fv && fv.NSName) out['Font'] = String(fv.NSName) + (fv.NSSize ? ' ' + fv.NSSize + ' pt' : '');
      } catch (_) {}
    }
    const colours = Object.keys(v).filter((k) => /Color$/.test(k));
    if (colours.length) out['Colour settings'] = colours.length;
  } else if (ext === 'itermcolors') {
    // An iTerm2 colour preset: each "<name> Color" holds 0-1 RGB components.
    const swatches: HTMLElement[] = [];
    const to255 = (x: any) => Math.max(0, Math.min(255, Math.round((Number(x) || 0) * 255)));
    for (const [name, c] of Object.entries<any>(v)) {
      if (!c || typeof c !== 'object' || c['Red Component'] == null) continue;
      const rgb = [to255(c['Red Component']), to255(c['Green Component']), to255(c['Blue Component'])];
      const hex = '#' + rgb.map((n) => n.toString(16).padStart(2, '0')).join('');
      swatches.push(el('div', { style: 'display:flex;align-items:center;gap:8px;font-family:var(--font-mono);font-size:12px;' }, [
        el('span', { style: 'width:28px;height:18px;flex:none;border:var(--bd-hairline);background:' + hex + ';' }),
        el('span', {}, hex + '  ' + name),
      ]));
    }
    if (swatches.length) {
      out['Colours'] = swatches.length;
      sections.push({ title: 'Palette (' + swatches.length + ')', open: true,
        node: el('div', { style: 'display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:6px 16px;' }, swatches) });
    }
  } else if (ext === 'aupreset') {
    // An Audio Unit plug-in preset (Logic, GarageBand, any AU host).
    if (v.name) out['Preset name'] = String(v.name);
    if (v.manufacturer != null) out['Manufacturer code'] = fourcc(v.manufacturer);
    if (v.type != null) out['Unit type'] = fourcc(v.type);
    if (v.subtype != null) out['Unit subtype'] = fourcc(v.subtype);
    if (v.version != null) out['Version'] = String(v.version);
    const blob = v.data || v['jucePluginState'] || v.vstdata;
    if (blob instanceof Uint8Array) out['State data'] = fmtBytes(blob.length);
  } else if (ext === 'stringsdict' || ext === 'strings') {
    const keys = Object.keys(v);
    out['Entries'] = keys.length;
    if (keys.length) sections.push({ title: 'Keys (' + keys.length + ')', node: preBlock(keys.slice(0, 500).join('\n') + (keys.length > 500 ? '\n…' : '')) });
  }

  const dump = plistDump(v);
  if (dump) sections.push({ title: 'Contents', node: dump });
  out._sections = sections;
  return out;
}

// ---------- Apple .strings (localisation table) ----------
// Text form `"key" = "value";` (often UTF-16), or a binary/XML plist since Xcode
// started compiling them - the plist case goes through parseMacPlist.
async function parseStrings(file: File) {
  const head = await readSlice(file, 0, 64);
  if (ascii(head, 0, 6) === 'bplist' || /^\s*<\?xml/.test(ascii(head, 0, Math.min(head.length, 64)))) return parseMacPlist(file, 'strings');
  const buf = await readSlice(file, 0, PARSE_TEXT_MAX);
  const enc = buf[0] === 0xFF && buf[1] === 0xFE ? 'utf-16le' : buf[0] === 0xFE && buf[1] === 0xFF ? 'utf-16be'
    : (buf.length > 3 && buf[1] === 0 && buf[3] === 0) ? 'utf-16le' : 'utf-8';
  const text = new TextDecoder(enc).decode(buf).replace(/^﻿/, '');
  const pairs: string[] = [];
  const re = /"((?:[^"\\]|\\.)*)"\s*=\s*"((?:[^"\\]|\\.)*)"\s*;/g;
  let m; let n = 0;
  while ((m = re.exec(text))) { n++; if (pairs.length < 500) pairs.push(m[1] + '  =  ' + m[2]); }
  if (!n) return null;
  const out: Row = { 'Format': 'Strings table (text, ' + enc.toUpperCase() + ')', 'Entries': n };
  out._sections = [{ title: 'Strings (' + n + (n > 500 ? ', first 500 shown' : '') + ')', node: preBlock(pairs.join('\n')), open: true }];
  return out;
}

// ---------- AppleDouble / AppleSingle (._name) ----------
// When a Mac copies a file to a disk that cannot hold Mac metadata (FAT, exFAT,
// NTFS, SMB shares) or into a zip, the metadata goes into a sibling file named
// `._<name>`: a header, then entries for the Finder info, the resource fork
// and - packed after the Finder info - every extended attribute. That last part
// is the forensic gold: com.apple.quarantine says which app downloaded the
// file and when, kMDItemWhereFroms says from which URL.
const AD_ENTRIES: Record<number, string> = {
  1: 'Data fork', 2: 'Resource fork', 3: 'Real name', 4: 'Comment', 5: 'Icon (black and white)',
  6: 'Icon (colour)', 8: 'File dates', 9: 'Finder info', 10: 'Macintosh file info', 11: 'ProDOS file info',
  12: 'MS-DOS file info', 13: 'AFP short name', 14: 'AFP file info', 15: 'AFP directory ID',
};
const FINDER_LABELS = ['', 'Grey', 'Green', 'Purple', 'Blue', 'Yellow', 'Red', 'Orange'];
const AD_EPOCH = 946684800;   // AppleSingle dates count seconds from 2000-01-01 UTC

async function parseAppleDouble(file: File) {
  const b = await readSlice(file, 0, SCAN_SMALL);
  if (b.length < 26) return null;
  const dv = new DataView(b.buffer, b.byteOffset, b.byteLength);
  const magic = dv.getUint32(0);
  if (magic !== 0x00051607 && magic !== 0x00051600) return null;
  const single = magic === 0x00051600;
  const out: Row = {
    'Format': single ? 'AppleSingle (a Mac file and its metadata in one)' : 'AppleDouble (Mac metadata kept beside a file)',
    'Version': (dv.getUint32(4) >>> 16) + '',
  };
  const real = (file.name || '').replace(/^.*[\\/]/, '').replace(/^\._/, '');
  if (!single && real) out['Describes'] = real;
  const home = latin1(b.subarray(8, 24)).replace(/\0/g, '').trim();
  if (home) out['Written by'] = home;
  out['_app'] = single ? 'macOS AppleSingle file' : 'macOS AppleDouble metadata';

  const count = Math.min(dv.getUint16(24), 64);
  const listed: string[] = [];
  const attrLines: string[] = [];
  for (let i = 0; i < count; i++) {
    const p = 26 + i * 12;
    if (p + 12 > b.length) break;
    const id = dv.getUint32(p), off = dv.getUint32(p + 4), len = dv.getUint32(p + 8);
    listed.push((AD_ENTRIES[id] || 'Entry ' + id) + '  ' + fmtBytes(len));
    if (off + len > b.length) continue;   // past the read window: listed, not decoded
    if (id === 3 && len) out['Original name'] = utf8(b.subarray(off, off + len));
    else if (id === 4 && len) out['Finder comment'] = utf8(b.subarray(off, off + len));
    else if (id === 1) out['Data fork'] = fmtBytes(len);
    else if (id === 2 && len) {
      out['Resource fork'] = fmtBytes(len);
      const types = resourceTypes(b, off, len);
      if (types.length) out['Resource types'] = types.join(', ');
    } else if (id === 8 && len >= 16) {
      const d = (k: number) => { const s = dv.getInt32(off + k); return s === -0x80000000 ? null : new Date((AD_EPOCH + s) * 1000); };
      const c = d(0), m = d(4);
      if (c) out['Created (Mac)'] = fmtDate(c);
      if (m) out['Modified (Mac)'] = fmtDate(m);
    } else if (id === 9 && len >= 32) {
      const type = latin1(b.subarray(off, off + 4)), creator = latin1(b.subarray(off + 4, off + 8));
      if (/[^\0]/.test(type)) out['File type code'] = type;
      if (/[^\0]/.test(creator)) out['Creator code'] = creator;
      const flags = dv.getUint16(off + 8);
      const label = FINDER_LABELS[(flags >> 1) & 7];
      if (label) out['Finder label'] = label;
      const fl = [];
      if (flags & 0x4000) fl.push('invisible');
      if (flags & 0x0400) fl.push('custom icon');
      if (flags & 0x8000) fl.push('alias');
      if (flags & 0x0800) fl.push('stationery');
      if (flags & 0x1000) fl.push('name locked');
      if (fl.length) out['Finder flags'] = fl.join(', ');
      if (len > 34 + 36 && ascii(b, off + 34, 4) === 'ATTR') await readXattrs(b, dv, off + 34, out, attrLines);
    }
  }
  const sections: any[] = [{ title: 'Entries (' + listed.length + ')', node: preBlock(listed.join('\n')) }];
  if (attrLines.length) sections.unshift({ title: 'Extended attributes (' + attrLines.length + ')', node: preBlock(attrLines.join('\n\n')), open: true });
  out._sections = sections;
  return out;
}

// The resource-fork type list (TEXT, icns, sfnt, url , ...): what the fork holds.
function resourceTypes(b: Uint8Array, off: number, len: number) {
  try {
    const dv = new DataView(b.buffer, b.byteOffset, b.byteLength);
    const mapOff = off + dv.getUint32(off + 4);
    if (mapOff + 30 > off + len) return [];
    const typeList = mapOff + dv.getUint16(mapOff + 24);
    const n = (dv.getUint16(typeList) + 1) & 0xFFFF;
    const out = [];
    for (let i = 0; i < Math.min(n, 64); i++) {
      const p = typeList + 2 + i * 8;
      if (p + 8 > off + len) break;
      out.push(latin1(b.subarray(p, p + 4)) + ' x' + (dv.getUint16(p + 4) + 1));
    }
    return out;
  } catch (_) { return []; }
}

// The xattr block packed after the Finder info: an 'ATTR' header, then entries
// of (offset, length, flags, name) whose offsets are from the start of the file.
async function readXattrs(b: Uint8Array, dv: DataView, h: number, out: Row, lines: string[]) {
  const n = Math.min(dv.getUint16(h + 34), 256);
  let p = h + 36;
  for (let i = 0; i < n; i++) {
    if (p + 11 > b.length) break;
    const off = dv.getUint32(p), len = dv.getUint32(p + 4), nameLen = b[p + 10];
    const name = utf8(b.subarray(p + 11, p + 11 + nameLen)).replace(/\0+$/, '');
    p += (11 + nameLen + 3) & ~3;
    if (off + len > b.length) { lines.push(name + '\n  ' + fmtBytes(len) + ' (outside the read window)'); continue; }
    const val = b.subarray(off, off + len);
    let shown = '';
    if (name === 'com.apple.quarantine') {
      // flags;hex-unix-time;agent;event-uuid
      const [flags, t, agent, uuid] = utf8(val).split(';');
      const when = parseInt(t, 16);
      if (agent) out['Quarantined by'] = agent;
      if (when) out['Quarantined at'] = fmtDate(new Date(when * 1000));
      shown = 'flags ' + flags + (when ? ', ' + new Date(when * 1000).toISOString() : '') + (agent ? ', by ' + agent : '') + (uuid ? ', event ' + uuid : '');
    } else if (name === 'com.apple.lastuseddate#PS' && len >= 8) {
      const s = Number(dv.getBigUint64(off, true));
      if (s > 0 && s < 1e11) { out['Last opened'] = fmtDate(new Date(s * 1000)); shown = new Date(s * 1000).toISOString(); }
    } else if (val.length >= 8 && ascii(val, 0, 6) === 'bplist') {
      let pv: any = null;
      try { const r = await parsePlist(val); pv = r && unarchiveKeyed(r.value); } catch (_) {}
      if (name === 'com.apple.metadata:kMDItemWhereFroms' && Array.isArray(pv)) {
        if (pv[0]) out['Downloaded from'] = String(pv[0]);
        if (pv[1]) out['Referring page'] = String(pv[1]);
      } else if (name === 'com.apple.metadata:kMDItemDownloadedDate' && Array.isArray(pv) && pv[0] instanceof Date) {
        out['Downloaded at'] = fmtDate(pv[0]);
      } else if (name === 'com.apple.metadata:_kMDItemUserTags' && Array.isArray(pv) && pv.length) {
        out['Tags'] = pv.map((t: any) => { const [tn, c] = String(t).split('\n'); return tn + (FINDER_LABELS[+c] && FINDER_LABELS[+c] !== tn ? ' (' + FINDER_LABELS[+c] + ')' : ''); }).join(', ');
      }
      try { shown = JSON.stringify(pv, (k, x) => (x instanceof Uint8Array ? '<' + x.length + ' bytes>' : x)); } catch (_) { shown = 'binary plist'; }
    } else if (len && !val.some((c) => c < 9 || (c > 13 && c < 32))) {
      shown = utf8(val);
    } else {
      shown = fmtBytes(len) + ' of binary data';
    }
    lines.push(name + '\n  ' + (shown.length > 600 ? shown.slice(0, 600) + '…' : shown));
  }
}

// ---------- dispatch ----------
export const PARSERS: Record<string, ParseFn> = {
  appledouble: (c) => parseAppleDouble(c.file),
  textclipping: (c) => parseMacPlist(c.file, c.ext),
  inetloc: (c) => parseMacPlist(c.file, c.ext),
  fileloc: (c) => parseMacPlist(c.file, c.ext),
  afploc: (c) => parseMacPlist(c.file, c.ext),
  ftploc: (c) => parseMacPlist(c.file, c.ext),
  savedsearch: (c) => parseMacPlist(c.file, c.ext),
  terminal: (c) => parseMacPlist(c.file, c.ext),
  itermcolors: (c) => parseMacPlist(c.file, c.ext),
  aupreset: (c) => parseMacPlist(c.file, c.ext),
  stringsdict: (c) => parseMacPlist(c.file, c.ext),
  strings: (c) => parseStrings(c.file),
  opml: (c) => parseOpml(c.file),
  rss: (c) => parseFeed(c.file),
  atom: (c) => parseFeed(c.file),
  agc: (c) => parseAndroidPrefs(c.file, c.ext),
  penc: (c) => parseSamsungEncrypted(c.file, c.ext),
  enc: (c) => parseSamsungEncrypted(c.file, c.ext),
  bk: (c) => parseSamsungBackup(c.file),
  desktop: (c) => parseDesktop(c.file),
  nfo: (c) => parseNfo(c.file),
  service: (c) => parseService(c.file),
  crash: (c) => parseCrash(c.file),
  ab: (c) => parseAb(c.file),
  job: (c) => parseJob(c.file),
  pol: (c) => parsePol(c.file),
  lst: (c) => parseFontList(c.file),
  // identification-only (rare AND hard)
  ds_store: () => identDsStore(),
  thumbsdb: () => identThumbsDb(),
  dsym: () => identDsym(),
  dwarf: () => identDsym(),
  sdb: () => identSdb(),
};
